            p0.y = (((StepSize * i) - ((GridLines * StepSize) / 2)) * uvGridSize) * uvGraphScale + UVGraphCenter.y + gridOffset.y;
            p1.y = p0.y;

            GL.Vertex(p0);
            GL.Vertex(p1);
